import { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import axios from "axios";
import "./App.css";

import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import UserDashboard from "./components/UserDashboard";
import VotingPage from "./components/VotingPage";

const API_URL = "http://localhost:5000";

function App() {
  // ===================== STATE =====================
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token"),
    role: localStorage.getItem("role"),
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    yearLevel: "",
    block: "",
    image: null,
  });

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 2000);
    return () => clearInterval(interval);
  }, []);

  // ================= AUTH =================
  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      Object.keys(candidateForm).forEach((key) => {
        if (candidateForm[key]) formData.append(key, candidateForm[key]);
      });

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        yearLevel: "",
        block: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  // ================= LOGIN CHECK =================
  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  return (
    <Router>
      <div className={darkMode ? "app dark" : "app"}>

        {/* NAVBAR */}
        <nav className="navbar">
          <h1 className="logo">SorSU Online Voting</h1>

          <div className="nav-actions">
            <button className="btn primary" onClick={() => setDarkMode(!darkMode)}>
              {darkMode ? "Light Mode" : "Dark Mode"}
            </button>

            {auth.role === "admin" && (
              <button
                className="btn secondary"
                onClick={() => setShowAnonymous(!showAnonymous)}
              >
                {showAnonymous ? "Hide Chart" : "Anonymous Chart"}
              </button>
            )}

            {auth.role === "admin" && (
              <button
                className={`btn ${electionClosed ? "success" : "danger"}`}
                onClick={() => setElectionClosed(!electionClosed)}
              >
                {electionClosed ? "Open Election" : "Close Election"}
              </button>
            )}

            <button className="btn danger" onClick={handleLogout}>
              Logout
            </button>
          </div>
        </nav>

        {/* CONTENT */}
        <div className="container">
          {message && <div className="alert">{message}</div>}

          <Routes>
            {/* ADMIN ROUTES */}
            {auth.role === "admin" && (
              <Route
                path="*"
                element={
                  showAnonymous ? (
                    <AdminAnonymousResults />
                  ) : (
                    <div className="card">
                      <h2>Live Vote Monitor</h2>
                      <p><strong>Total Votes:</strong> {totalVotes}</p>

                      <AdminPanel
                        candidateForm={candidateForm}
                        setCandidateForm={setCandidateForm}
                        onSave={handleSaveCandidate}
                        editId={editId}
                        setEditId={setEditId}
                        onDelete={handleDeleteCandidate}
                        candidates={candidates}
                      />
                    </div>
                  )
                }
              />
            )}

            {/* USER ROUTES */}
            {auth.role === "user" && (
              <>
                <Route path="/dashboard" element={<UserDashboard auth={auth} />} />
                <Route path="/vote" element={<VotingPage auth={auth} />} />
                <Route path="*" element={<Navigate to="/dashboard" />} />
              </>
            )}
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
